function exportCSV(){const columns=['Barcode','Format','Item Name','Asset Tag','Serial Number','Category','Description','Location','Assigned To','Quantity','Notes','Scan Source','Date','Time'];const rows=scans.map(scan=>{const item=inventory.find(i=>i.barcode===scan.barcode)||{};return [scan.barcode,scan.format,...fields.slice(1).map(([k])=>item[k]??''),scan.source,new Date(scan.at).toLocaleDateString(),new Date(scan.at).toLocaleTimeString()]});const blob=new Blob(['\uFEFF'+[columns,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`barcode-scans-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('CSV exported. In Excel, import Barcode as Text to preserve leading zeros.')}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)setPage(b.dataset.page);if(b.dataset.close)$('#'+b.dataset.close).close();if(b.dataset.copy)copy(b.dataset.copy);if(b.dataset.edit)details(b.dataset.edit);if(b.dataset.view){setPage('inventory');$('#inventory-search').value=b.dataset.view;render()}if(b.dataset.rescan||['scan-again','scan-another','empty-start'].includes(b.id)){setPage('scanner');startCamera()}if(b.id==='create-asset-from-scan'&&current?.barcode&&window.mdmCreateAssetFromScan)await window.mdmCreateAssetFromScan(current.barcode);if(b.dataset.delete){try{await mutate('scans','delete',b.dataset.delete);scans=scans.filter(s=>s.id!==b.dataset.delete);render();notify('Scan deleted.')}catch{notify('The scan could not be deleted. Try again.')}}});
