$('#upload-scan-open').onclick=()=>{stopCamera();$('#upload-scan-form').reset();$('#upload-preview-wrap').hidden=true;$('#upload-analysis-results').hidden=true;$('#upload-analysis-status').textContent='';$('#upload-use-result').disabled=true;$('#upload-scan-dialog').showModal()};
$('#upload-scan-file').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){notify('Choose an image file.');return}if(file.size>12*1024*1024){notify('Use an image smaller than 12 MB.');return}try{await analyzeUploadedLabel(file)}catch{notify('The image could not be analyzed. Try a clearer photo.',true)}};
$('#upload-use-result').onclick=async()=>{const value=$('#upload-identifier-candidate').value.trim();if(!value){notify('Enter or select an identifier first.');return}const box=$('#upload-analysis-results');$('#upload-scan-dialog').close();await record(value,box.dataset.format||'Image / OCR','Image Upload',{ocrText:box.dataset.ocrText||'',serviceTag:box.dataset.serviceTag||'',serialNumber:box.dataset.serialNumber||''})};
$('#start').onclick=()=>startCamera();$('#stop').onclick=()=>stopCamera();$('#switch').onclick=()=>{const index=cameras.findIndex(c=>c.deviceId===$('#camera-select').value);startCamera(cameras[(index+1)%cameras.length].deviceId)};$('#camera-select').onchange=e=>startCamera(e.target.value);$('#torch').onclick=async()=>{try{const next=!torchOn;await stream.getVideoTracks()[0].applyConstraints({advanced:[{torch:next}]});torchOn=next;$('#torch').textContent=next?'Flashlight off':'Flashlight'}catch{notify('Flashlight is unavailable on this camera.');$('#torch').hidden=true}};
$('#manual-open').onclick=()=>{stopCamera();$('#manual-dialog').showModal()};
$('#manual-inline-search').onclick=async()=>{const value=$('#manual-inline').value.trim();if(!value){notify('Enter an asset tag, barcode, or serial number.');return}const button=$('#manual-inline-search');button.disabled=true;try{if(window.mdmAssetLookup)await window.mdmAssetLookup(value);else await record(value,'Unknown / Manual','Manual Lookup')}finally{button.disabled=false}};
$('#manual-inline').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('#manual-inline-search').click()}});$('#manual-form').onsubmit=async e=>{e.preventDefault();const value=new FormData(e.target).get('barcode').trim();if(!value){notify('Enter a barcode value.');return}if(await record(value,'Unknown / Manual','Manual')){$('#manual-dialog').close();e.target.reset();setPage('scanner')}};
$('#details-form').onsubmit=async e=>{e.preventDefault();const item=Object.fromEntries(new FormData(e.target));item.barcode=editingBarcode;item.quantity=Number(item.quantity);try{await mutate('inventory','put',item);inventory=inventory.filter(i=>i.barcode!==item.barcode);inventory.unshift(item);$('#details-dialog').close();render();if(current)showResult(current);notify('Inventory record saved.')}catch{notify('This record could not be saved. Your entered details are still available. Try again.',true)}};
$('#history-search').oninput=render;$('#inventory-search').oninput=render;$('#export').onclick=exportCSV;$('#clear').onclick=()=>$('#confirm-dialog').showModal();$('#confirm-clear').onclick=async()=>{try{await mutate('scans','clear');scans=[];current=null;$('#result').hidden=true;$('#confirm-dialog').close();render();notify('Scan history cleared.')}catch{notify('History could not be cleared. Try again.')}};
for(const key of Object.keys(defaults))$('#'+key).onchange=async e=>{settings[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;theme();try{await mutate('settings','put',{...settings,id:'preferences'})}catch{notify('Settings could not be saved.')}};
window.addEventListener('pagehide',stopCamera);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopCamera()});matchMedia('(prefers-color-scheme: dark)').addEventListener('change',theme);
(async()=>{try{db=await openDB();[scans,inventory]=await Promise.all([all('scans'),all('inventory')]);const saved=await all('settings');if(saved.length)settings={...defaults,...saved[0]};db.onversionchange=()=>{db.close();notify('Reload to use the updated local storage.',true)}}catch{notify('Local storage is unavailable. Enable browser storage and reload before saving scans.',true)}for(const key of Object.keys(defaults)){const e=$('#'+key);e.type==='checkbox'?e.checked=settings[key]:e.value=settings[key]}theme();render();if(navigator.mediaDevices?.enumerateDevices)listCameras()})();

async function checkSession(){try{const response=await fetch('/api/auth/me',{cache:'no-store',credentials:'same-origin'});if(response.status===401){stopCamera();location.replace('/login');return}if(response.ok){const result=await response.json();$('#account-email').textContent=result.user.email;if($('#account-role'))$('#account-role').textContent=String(result.user.role||'Workspace').replaceAll('_',' ');if($('#account-name'))$('#account-name').textContent=result.user.name||result.user.email?.split('@')[0]||'Account'}}catch{notify('Connection unavailable. Check your connection before continuing.')}}
$('#logout').onclick=async()=>{stopCamera();try{const response=await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin'});if(!response.ok)throw Error();location.replace('/login')}catch{notify('Unable to sign out. Please retry.')}};
window.addEventListener('pageshow',checkSession);setInterval(checkSession,60000);

function updateSessionUI(){const mode=$('#scan-mode')?.value||'quick',wrap=$('#scan-session-wrap'),progress=$('#inventory-progress'),label=$('#session-mode-label');if(label)label.textContent=mode==='inventory'?'Inventory Audit':$('#scan-mode')?.selectedOptions?.[0]?.textContent||'Quick Scan';if(wrap)wrap.hidden=mode!=='inventory';if(progress){const option=$('#scan-session')?.selectedOptions?.[0],expected=Number(option?.dataset.expected||0),sessionId=$('#scan-session')?.value||'',count=sessionId?scans.filter(s=>s.sessionId===sessionId).length:0;progress.hidden=mode!=='inventory'||!expected;if(expected){$('#inventory-progress-label').textContent=count+' of '+expected+' assets';$('#inventory-progress-bar').style.width=Math.min(100,count/expected*100)+'%'}}}
$('#scan-mode')?.addEventListener('change',()=>{updateSessionUI();render()});
$('#scan-session')?.addEventListener('change',updateSessionUI);

const setOfflineState=()=>{const banner=$('#offline-banner');if(banner)banner.hidden=navigator.onLine};window.addEventListener('online',setOfflineState);window.addEventListener('offline',setOfflineState);setOfflineState();

const globalSearch=$('#global-search');document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();globalSearch?.focus()}});
globalSearch?.addEventListener('keydown',e=>{if(e.key==='Enter'&&globalSearch.value.trim()){e.preventDefault();setPage('records');const q=$('#cloud-search');if(q){q.value=globalSearch.value.trim();q.dispatchEvent(new Event('input',{bubbles:true}))}}});

let keyboardBuffer='',keyboardAt=0;document.addEventListener('keydown',async e=>{const active=!$('#scanner')?.hidden;if(!active||e.ctrlKey||e.metaKey||e.altKey||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;const now=performance.now();if(now-keyboardAt>120)keyboardBuffer='';keyboardAt=now;if(e.key==='Enter'){const value=keyboardBuffer.trim();keyboardBuffer='';if(value.length>=4){e.preventDefault();$('#external-scanner-state').innerHTML='<span class="status-dot"></span> External Scanner Listening';await record(value,'Keyboard','External Scanner');setTimeout(()=>{$('#external-scanner-state').innerHTML='<span class="status-dot"></span> External Scanner Ready'},800)}return}if(e.key.length===1)keyboardBuffer+=e.key});

function routeFromLocation(){if(location.pathname==='/assets/scanner')return'scanner';if(location.hash)return location.hash.slice(1);return'dashboard'}
window.addEventListener('popstate',()=>setPage(routeFromLocation(),false));setPage(routeFromLocation(),false);
